\begin{center}
\begin{tikzpicture}[scale=0.62, line cap=round,line join=round,font=\footnotesize,>=stealth]
    \def\r{3}
    \path 
    (0,0) coordinate (O)
    ++(0:\r) coordinate (M1)
    (O)++(0:3*\r) coordinate (A)
    ;
    \begin{scope}
        \draw[name path = dtronO] let \p1=($ (O) - (M1) $) in (O) circle ({veclen(\x1,\y1)});
        \path ($(O)!0.5!(A)$) coordinate (OA);
        \path[name path=dtronT] let \p1=($(OA) - (O)$) in (OA) circle ({veclen(\x1,\y1)});
        \path[name intersections={of=dtronO and dtronT, by={B,C}}];
        \draw (B)--(A)--(C);
    \end{scope}
    \path 
    ($(C)!2!(O)$) coordinate (D)
    ($(C)!(B)!(D)$) coordinate (H)
    (intersection of A--D and B--H) coordinate (I)
    ($(D)!(O)!(I)$) coordinate (H1)
    ($(D)!2!(H1)$) coordinate (E)
    (intersection of O--A and B--C) coordinate (M)
    ;
    \draw (C)--(D)--(B)--cycle (B)--(H) (A)--(D) (B)--(O)--(A);

         \filldraw[black] (A) circle (1pt) node[above right] {$A$};
    \filldraw[black] (B) circle (1pt) node[above right] {$B$};
    \filldraw[black] (C) circle (1pt) node[below] {$E$};
   \filldraw[black] (D) circle (1pt) node[above left]{$F$};
    \filldraw[black] (E) circle (1pt) node[above right] {$G$};

 \filldraw[black] (M) circle (1pt) node[above right] {$Y$};
    \filldraw[black] (I) circle (1pt) node[above] {$K$};
    \filldraw[black] (H) circle (1pt) node[above left] {$S$};

    \filldraw[black] (O) circle (1pt) node[below left ] {$O$};
\end{tikzpicture}
\end{center}
Ta có ${B}$ thuộc $(O)$ và có ${EF}$ là đường kính của $({O})$\\
$\Rightarrow \triangle {BEF}$ nội tiếp $(O; \dfrac{EF}{2})$\\
$\Rightarrow \triangle {BEF}$ vuông tại ${B}$\\
$\Rightarrow \widehat{EBF} = 90^{\circ}$\\
$\Rightarrow {BF \perp BE}$\\
Vì ${AB, AE}$ là hai tiếp tuyến của $({O})$ nên ${AB = AE}$ (tính chất)\\
$\Rightarrow \triangle {ABE}$ cân tại ${A}$\\
Lại có ${O}$ là tâm đường tròn $({O})$, $\widehat{BAE}$\\
$\Rightarrow AO \perp BE$ trong tam giác $\triangle {ABE}$\\
$\Rightarrow {AO \perp BE}$\\
Ta có ${BF \perp BE, AO \perp BE}$. Suy ra ${BF \parallel AO}$\\
b) Ta có ${G}$ thuộc $({O})$ và có ${EF}$ là đường kính của $({O})$\\
Suy ra $\triangle {EFG}$ nội tiếp $({O; \dfrac{EF}{2} })$\\
Suy ra $\triangle {EFG}$ vuông tại ${G}$\\
Suy ra $\widehat{EGF} = 90^{\circ}$\\
Suy ra ${EG \perp AF}$\\
Xét hai tam giác $\triangle {AGE}$ và $\triangle {AEF}$ có:\\
$\widehat{AGE} = \widehat{AEF} = 90^{\circ}$\\
$\widehat{A}$ chung\\
Vậy $\triangle {AGE}$ đồng dạng với $\triangle {AEF}$\\
$\Rightarrow \dfrac{AG}{AE} = \dfrac{AE}{AF} \Rightarrow AE^{2} = AG.AE$\\
Mà ${AB = AE}$\\
${\Rightarrow AB^{2} = AG.AE }$\\
c) Xét hai tam giác $\triangle {SFB}$ và $\triangle {EOA}$ có:\\
$\widehat{FSB} = \widehat{OEA} = 90^{\circ}$\\
$\widehat{SFB} = \widehat{EOA}$ (đồng vị và ${BF \parallel AO}$)\\
Vậy $\triangle {SFB}$ đồng dạng với $\triangle {EOA}$\\
Suy ra $\dfrac{SF}{OE} = \dfrac{BS}{AE} \Rightarrow SF = \dfrac{BS}{2AE}$\\
Mà ${EF = 2OE, BS = 2SK}$ (vì ${O, K}$ lần lượt là trung điểm của ${EF, BS}$)\\
Suy ra $\dfrac{SF}{EF} = \dfrac{SK}{AE}$\\
Xét hai tam giác $\triangle {SFK}$ và $\triangle {EFA}$ có:\\
$\widehat{FSK} = \widehat{FEA} = 90^{\circ}$\\
$\dfrac{SF}{EF} = \dfrac{SK}{AE}$\\
Vậy $\triangle {SFK}$ đồng dạng với $\triangle {EFA}$\\
Suy ra ${SFK = EFA}$\\
Suy ra hai tia ${FK, FA}$ trùng nhau\\
Vậy ba điểm ${A, K, F}$ thẳng hàng
}\end{ex}

